{
 "command": "cat scripts/backfill_tax.py && ls scripts && git log --oneline -3",
 "description": "Show backfill script and scripts dir"
}

{
 "command": "cat src/billing/periods.py; echo \"DATABASE_URL set: ${DATABASE_URL:+yes}\"; echo \"BACKFILL_BATCH=${BACKFILL_BATCH}\"",
 "description": "Show month_window and check env vars"
}

{
 "command": "python scripts/backfill_tax.py --month 2026-09 --batch-size 500; echo \"exit=$?\"; echo \"TZ=$TZ\"; date +%Z",
 "description": "Run September tax backfill dry run"
}

{
 "command": "TZ=UTC python scripts/backfill_tax.py --month 2026-09 --batch-size 500; echo \"exit=$?\"",
 "description": "Rerun backfill dry run with UTC timezone"
}
